(()=>{
'use strict';const $=s=>document.querySelector(s),core=window.WaveLesson,num=window.LinearLesson;
function math(host,tex){const e=document.createElement('span');e.dataset.tex=tex;host.replaceChildren(e);}
function piTex(n,d=1){const q=num.rational(n,d);if(q.n===0)return '0';const top=Math.abs(q.n)===1?'\\pi':Math.abs(q.n)+'\\pi';return(q.n<0?'-':'')+(q.d===1?top:`\\frac{${top}}{${q.d}}`);}
function path(points){return points.map((p,i)=>`${i?'L':'M'}${p.x.toFixed(3)} ${p.y.toFixed(3)}`).join(' ');}
function grid(host,xmax,ymax,levels){let s='';for(let i=0;i<=4;i++){const p=core.point(xmax*i/4,0,xmax,ymax);s+=`<line x1="${p.x}" x2="${p.x}" y1="25" y2="265" class="wave-grid-line"/>`;}for(const y of levels){const p=core.point(0,y,xmax,ymax);s+=`<line x1="48" x2="610" y1="${p.y}" y2="${p.y}" class="${y===0?'wave-axis':'wave-grid-line'}"/><text x="38" y="${p.y+5}" text-anchor="end" class="wave-grid-label">${y}</text>`;}s+='<path d="M48 25V265" class="wave-axis"/>';host.innerHTML=s;}
grid($('#trace-grid'),2*Math.PI,1.5,[-1,0,1]);grid($('#wave-grid'),4*Math.PI,5,[-5,-3,-1,0,1,3,5]);
$('#trace-sin').setAttribute('d',path(core.curve({kind:'sin'},2*Math.PI,1.5)));$('#trace-cos').setAttribute('d',path(core.curve({kind:'cos'},2*Math.PI,1.5)));
function trace(){const n=Number($('#trace-angle').value),x=n*Math.PI/12,s=core.value(x),c=core.value(x,{kind:'cos'}),p=core.point(x,s,2*Math.PI,1.5),q=core.point(x,c,2*Math.PI,1.5),cx=120+85*c,cy=120-85*s;$('#trace-output').value=(n*15)+'°';$('#trace-radius').setAttribute('x2',cx);$('#trace-radius').setAttribute('y2',cy);$('#trace-projection').setAttribute('d',`M120 ${cy}H${cx}V120`);$('#trace-point').setAttribute('cx',cx);$('#trace-point').setAttribute('cy',cy);for(const [id,v] of [['sin-dot',p],['cos-dot',q]]){ $('#'+id).setAttribute('cx',v.x);$('#'+id).setAttribute('cy',v.y);}for(const [key,v] of Object.entries({x1:p.x,x2:p.x,y1:25,y2:265}))$('#trace-guide').setAttribute(key,v);math($('#trace-values'),String.raw`\theta=${piTex(n,12)},\quad\sin\theta\approx${s.toFixed(3).replace('.','{,}')},\quad\cos\theta\approx${c.toFixed(3).replace('.','{,}')}`);const note=`Sudut ${n*15} derajat. Sinus sekitar ${s.toFixed(3)} dan kosinus sekitar ${c.toFixed(3)}.`;$('#trace-circle').setAttribute('aria-label','Lingkaran satuan. '+note);$('#trace-plot').setAttribute('aria-label','Grafik sinus hijau dan kosinus jingga, dari nol sampai dua pi. '+note);$('#trace-note').textContent=n===24?'Satu putaran selesai: nilai dan arah gerak kembali ke pola awal.':n===6?'Sinus mencapai puncak; setelah ini sinus mulai turun, walaupun sudut terus bertambah.':n===18?'Sinus mencapai lembah; setelah ini sinus mulai naik.':'Sudut dibaca pada sumbu mendatar grafik, sedangkan tinggi titik menunjukkan nilai fungsi.';}
$('#trace-angle').addEventListener('input',trace);document.querySelectorAll('[data-trace]').forEach(e=>e.addEventListener('click',()=>{$('#trace-angle').value=e.dataset.trace;trace();}));trace();
function draw(){const config={kind:$('#wave-kind').value,a:Number($('#wave-a').value),b:Number($('#wave-b').value),h:Number($('#wave-h').value)*Math.PI,k:Number($('#wave-k').value)},s=core.stats(config);$('#a-output').value=config.a;$('#k-output').value=config.k;$('#wave-path').setAttribute('d',path(core.curve(config,4*Math.PI,5)));const y=core.point(0,config.k,4*Math.PI,5).y;for(const [key,v]of Object.entries({x1:48,x2:610,y1:y,y2:y}))$('#wave-midline').setAttribute(key,v);const h=Number($('#wave-h').value),inside=h===0?'x':h>0?String.raw`x-${piTex(h*2,2)}`:String.raw`x+${piTex(-h*2,2)}`,b=config.b===0.5?String.raw`\frac12`:String(config.b);math($('#wave-formula'),String.raw`y=${config.a}\,${config.kind==='sin'?String.raw`\sin`:String.raw`\cos`}\!\left(${b}\left(${inside}\right)\right)${config.k<0?'':'+'}${config.k}`);math($('#wave-stats'),String.raw`\text{Amplitudo}=${s.amplitude},\quad y_{\text{tengah}}=${s.midline},\quad\text{range}=[${s.min},${s.max}]`+(s.period===null?'':String.raw`,\quad T=${piTex(2/config.b)}`));const note=config.a===0?'Pengali tegak nol membuat grafik konstan. Amplitudonya nol; tidak ada periode positif terkecil karena setiap pergeseran mendatar mengulang garis yang sama.':`Amplitudo ${s.amplitude}; periode ${2/config.b} pi radian. ${config.a<0?'Pengali negatif membalik gelombang terhadap garis tengah. ':''}Jendela tetap menampilkan sudut nol sampai empat pi.`;$('#wave-note').textContent=note;$('#wave-plot').setAttribute('aria-label',`Grafik ${config.kind==='sin'?'sinus':'kosinus'} dengan pengali ${config.a}, koefisien sudut ${config.b}, pergeseran mendatar ${h} pi, pergeseran tegak ${config.k}. Range ${s.min} sampai ${s.max}. ${note}`);}
for(const id of ['wave-kind','wave-a','wave-b','wave-h','wave-k'])$('#'+id).addEventListener('input',draw);function preset(a,b,h,k){$('#wave-kind').value='sin';$('#wave-a').value=a;$('#wave-b').value=b;$('#wave-h').value=h;$('#wave-k').value=k;draw();}$('#wave-example').addEventListener('click',()=>preset(-2,2,0.5,1));$('#wave-reset').addEventListener('click',()=>preset(1,1,0,0));draw();
const questions=[{tex:String.raw`y=-3\sin x+2`,prompt:'Berapa amplitudonya?',n:3,d:1,hint:'Amplitudo adalah besar pengali tegak, tanpa tanda negatif.',why:'Amplitudo adalah nilai mutlak negatif tiga, yaitu tiga.'},{tex:String.raw`y=\cos(2x),\quad T=c\pi`,prompt:'Berapa nilai koefisien periode tersebut?',n:1,d:1,hint:'Periode adalah dua pi dibagi koefisien sudut.',why:'Dua pi dibagi dua adalah pi, sehingga koefisiennya satu.'},{tex:String.raw`y=2\sin x-1`,prompt:'Berapa nilai maksimum fungsi ini?',n:1,d:1,hint:'Nilai maksimum adalah garis tengah ditambah amplitudo.',why:'Garis tengah negatif satu ditambah amplitudo dua menghasilkan satu.'}];const solved=new Set();function report(i,ok,text){const e=$('#feedback'+i);e.className='feedback '+(ok?'correct':'incorrect');e.textContent=text;if(ok)solved.add(i);$('#progress').textContent=`${solved.size} dari 6 latihan sudah dijawab tepat.`;}
$('#questions').innerHTML=questions.map((q,i)=>`<div class="question"><h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><p>${q.prompt}</p><form data-question="${i}"><label for="answer${i}">Jawabanmu</label><div class="answer-line"><input id="answer${i}" type="text" required autocomplete="off" aria-describedby="feedback${i}"><button class="button" type="submit">Periksa jawaban</button></div></form><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Butuh petunjuk?</summary><p>${q.hint}</p></details><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details></div>`).join('');document.querySelectorAll('form[data-question]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const i=Number(form.dataset.question),q=questions[i],a=num.parseAnswer($('#answer'+i).value),ok=num.equalAnswer(a,num.rational(q.n,q.d));report(i,ok,ok?'Tepat. '+q.why:!a?'Tulis satu bilangan, misalnya 3/4 atau 1.':'Belum tepat. Periksa pengali di luar fungsi, koefisien sudut, dan garis tengah.');}));
const choices=[{tex:String.raw`y=\sin(2x-\pi)`,prompt:'Berapa pergeseran mendatarnya dari sinus yang sudah dipersempit?',options:[{text:'Ke kanan pi.'},{text:'Ke kanan setengah pi.'},{text:'Ke kiri setengah pi.'}],answer:1,why:'Faktorkan bagian dalam menjadi dua kali kurung x dikurangi setengah pi. Pergeserannya ke kanan setengah pi.'},{tex:String.raw`y=\sin x`,prompt:'Mengapa jarak nol ke pi bukan periode fungsi sinus?',options:[{text:'Nilainya kembali nol, tetapi arah gerak dan pola belum sama.'},{text:'Sinus tidak pernah bernilai nol.'},{text:'Periode ditentukan oleh tinggi puncak.'}],answer:0,why:'Pada nol sinus bergerak naik, sedangkan pada pi bergerak turun. Seluruh pola berulang setelah dua pi.'},{tex:String.raw`y=0\sin(2x)+1`,prompt:'Apa yang terjadi pada grafik ini?',options:[{text:'Gelombang beramplitudo satu.'},{text:'Tidak terdefinisi.'},{text:'Garis konstan setinggi satu, tanpa periode positif terkecil.'}],answer:2,why:'Pengali nol menghapus gelombang. Setiap pergeseran mendatar mengulang garis yang sama, sehingga tidak ada periode positif terkecil.'}];for(let j=0;j<choices.length;j++){const i=j+3,q=choices[j],box=document.createElement('div');box.className='question';box.innerHTML=`<h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><fieldset><legend>${q.prompt}</legend>${q.options.map((o,k)=>`<label class="choice"><input type="radio" name="choice${i}" value="${k}" ${o.label?'aria-label="'+o.label+'"':''}>${o.tex?'<span data-tex="'+o.tex+'"></span>':o.text}</label>`).join('')}</fieldset><button type="button" class="button" data-check="${i}">Periksa jawaban</button><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details>`;$('#questions').append(box);box.querySelector('button').addEventListener('click',()=>{const a=$(`[name="choice${i}"]:checked`),ok=!!a&&Number(a.value)===q.answer;report(i,ok,!a?'Pilih jawaban dahulu.':(ok?'Tepat. ':'Belum tepat. ')+q.why);});}
const storage={get(k){try{return localStorage.getItem('fondasi-waves-'+k)}catch{return null}},set(k,v){try{localStorage.setItem('fondasi-waves-'+k,v);return true}catch{return false}}};$('#reflection').value=storage.get('reflection')||'';$('#reflection').addEventListener('input',()=>{$('#save-note').textContent=storage.set('reflection',$('#reflection').value)?'Catatan tersimpan di peramban ini.':'Catatan belum dapat disimpan; salin jika diperlukan.';});function complete(saved){$('#complete').textContent='Bacaan sudah ditandai selesai ✓';$('#complete-note').textContent=saved?'Kemajuan tersimpan di peramban ini. Kamu bisa mencoba kembali kapan saja.':'Bacaan selesai; kemajuan belum dapat disimpan di peramban ini.';}$('#complete').addEventListener('click',()=>complete(storage.set('complete','yes')));if(storage.get('complete')==='yes')complete(true);
})();